style.css:
/* Global background */
body {
    background-color: #ffebf0 !important;
    color: #5a3e4d !important;
    font-family: 'Arial', sans-serif;
}

/* Links */
a {
    color: #d63384 !important;
    text-decoration: none !important;
}

a:hover {
    color: #ff66a3 !important;
    text-decoration: underline !important;
}

/* Buttons */
button, input[type="submit"], input[type="button"] {
    background-color: #ff66a3 !important;
    color: white !important;
    border: none !important;
    padding: 10px 15px !important;
    border-radius: 5px !important;
    cursor: pointer !important;
}

button:hover, input[type="submit"]:hover, input[type="button"]:hover {
    background-color: #e64c84 !important;
}

/* Text Inputs */
input[type="text"], textarea, select {
    background-color: #ffd6e3 !important;
    border: 1px solid #ff66a3 !important;
    color: #5a3e4d !important;
    padding: 8px !important;
    border-radius: 4px !important;
}

/* Headers */
h1, h2, h3, h4, h5, h6 {
    color: #b3005e !important;
}

/* Cards and Sections */
div, section, article {
    background-color: #ffe6ec !important;
    border-radius: 10px !important;
    padding: 15px !important;
    margin: 10px !important;
    box-shadow: 2px 2px 10px rgba(0, 0, 0, 0.1) !important;
}

/* Navbar */
nav {
    background-color: #ff99c8 !important;
    padding: 10px !important;
    border-radius: 0 0 10px 10px !important;
}

nav a {
    color: white !important;
    font-weight: bold !important;
    padding: 10px !important;
}

/* Footer */
footer {
    background-color: #ff99c8 !important;
    padding: 15px !important;
    text-align: center !important;
    color: white !important;
}
